// План specs/invoices.md 3.2 (кейс .qa/tests/invoices/IN-06). PROD, admin, компания «test», десктоп, EN.
// @writes @data: два счёта (клиент QA-unit client, $1) с позициями «QA-AUTO a901 race A/B …»; в конце — Actions → Delete обоих.
import { test, expect } from '../../fixtures';
import {
  PROD_CLIENT, PROD_ROLE, addManualItem, invoiceNameRow, invoiceNumber, openNewInvoiceProd, pickCustomer, prepareProdTest,
  removeDocumentAt, stamp, waitInvoiceCreated,
} from './invoice-helpers';

test.describe('Счета — номер нового счёта (#a901b1)', () => {
  test('QA-AUTO: two tabs press Create Invoice at the same moment → different numbers, each tab shows its own, name = number #a901b1 @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(180_000);
    const tabA = await asUser(PROD_ROLE);
    const tabB = await tabA.context().newPage(); // вторая вкладка той же сессии
    const urls: Record<'A' | 'B', string | null> = { A: null, B: null };
    const mark = stamp();
    try {
      for (const [key, tab] of [['A', tabA], ['B', tabB]] as const) {
        await prepareProdTest(tab);
        await openNewInvoiceProd(tab);
        await pickCustomer(tab, PROD_CLIENT);
        await addManualItem(tab, { name: `QA-AUTO a901 race ${key} ${mark}`, price: '1' });
        await expect(tab.getByRole('button', { name: 'Create Invoice' })).toBeEnabled();
      }

      // Почти одновременно (реджект: дубли при < 0.2 с между кликами)
      await Promise.all([
        tabA.getByRole('button', { name: 'Create Invoice' }).click(),
        tabB.getByRole('button', { name: 'Create Invoice' }).click(),
      ]);
      const [a, b] = await Promise.all([waitInvoiceCreated(tabA), waitInvoiceCreated(tabB)]);
      urls.A = a.url;
      urls.B = b.url;

      // Разные номера (источник: «מה רצוי» — «לא ייתכנו שני מספרי חשבונית זהים»)
      expect(a.number, 'номера двух счетов разные').not.toBe(b.number);

      for (const [tab, created] of [[tabA, a], [tabB, b]] as const) {
        // Invoice name = номер (коммент программиста 12.11 — имя, равное номеру, идёт за номером)
        await expect(invoiceNameRow(tab).getByRole('button', { name: created.number, exact: true })).toBeVisible();
        // Вкладка показывает именно сохранённый номер: после перезагрузки тот же
        await tab.reload();
        await expect.poll(() => invoiceNumber(tab), { message: 'номер после перезагрузки = показанному' }).toBe(created.number);
        await expect(invoiceNameRow(tab).getByRole('button', { name: created.number, exact: true })).toBeVisible();
      }
    } finally {
      await removeDocumentAt(tabA, urls.A, `QA-AUTO a901 race A ${mark}`);
      await removeDocumentAt(tabA, urls.B, `QA-AUTO a901 race B ${mark}`);
    }
  });
});
